run_shell {"command": "cd /home/agent/project && find src/invoice_tool -type f -name '*.py' | head -100 && echo --- && python3 - <<'EOF'
import ast, pathlib
for p in sorted(pathlib.Path("src/invoice_tool").rglob("*.py")):
    try:
        tree = ast.parse(p.read_text(), filename=str(p))
    except Exception as e:
        print(f"{p}: parse error: {e}")
        continue
    def walk(node, prefix=""):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if ast.get_docstring(child) is None:
                    print(f"{p}:{child.lineno}: {prefix}{child.name}")
                walk(child, prefix + child.name + ".")
            elif isinstance(child, ast.ClassDef):
                walk(child, prefix + child.name + ".")
            else:
                walk(child, prefix)
    walk(tree)
EOF"}
